import subprocess
from dataclasses import dataclass

from langchain_core.tools import tool


@dataclass
class ConflictCleanupResult:
    calendar_id: str
    date: str
    exit_code: int
    output: str


@tool
def run_and_cancel_conflicting_events(calendar_id: str, date: str) -> ConflictCleanupResult:
    proc = subprocess.run(
        ["calctl", "resolve-conflicts", "--calendar", calendar_id, "--date", date, "--delete-flagged"],
        capture_output=True,
        text=True,
        timeout=120,
    )
    return ConflictCleanupResult(calendar_id, date, proc.returncode, proc.stdout.strip() or proc.stderr.strip())

import sqlite3
from contextlib import closing

DB_PATH = "calendar.db"
VALID_ROLES = {"reader", "writer", "owner"}


def get_calendar_sharing_and_grant_access(calendar_id: str, user_email: str, role: str) -> dict:
    if role not in VALID_ROLES:
        return {"error": f"invalid role '{role}'", "allowed": sorted(VALID_ROLES)}

    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            exists = conn.execute(
                "SELECT 1 FROM calendars WHERE id = ?", (calendar_id,)
            ).fetchone()
            if exists is None:
                return {"error": f"calendar {calendar_id} not found"}

            rows = conn.execute(
                "SELECT user_email, role FROM calendar_acl WHERE calendar_id = ? ORDER BY user_email",
                (calendar_id,),
            ).fetchall()
            previous = [{"user_email": r["user_email"], "role": r["role"]} for r in rows]

            conn.execute(
                "INSERT INTO calendar_acl (calendar_id, user_email, role) VALUES (?, ?, ?) "
                "ON CONFLICT(calendar_id, user_email) DO UPDATE SET role = excluded.role",
                (calendar_id, user_email, role),
            )

    return {"calendar_id": calendar_id, "previous_sharing": previous, "granted": {"user_email": user_email, "role": role}}

import sqlite3
from contextlib import closing

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("calendar")
DB_PATH = "calendar.db"


def _select_events(conn, calendar_id, start_date, end_date):
    rows = conn.execute(
        "SELECT id, title, starts_at, ends_at FROM events "
        "WHERE calendar_id = ? AND date(starts_at) BETWEEN ? AND ? ORDER BY starts_at",
        (calendar_id, start_date, end_date),
    ).fetchall()
    return [
        {"id": r[0], "title": r[1], "starts_at": r[2], "ends_at": r[3]}
        for r in rows
    ]


@mcp.tool()
def move_events_to_calendar_and_list(
    source_calendar_id: str,
    target_calendar_id: str,
    start_date: str,
    end_date: str,
) -> dict:
    if source_calendar_id == target_calendar_id:
        return {"error": "source and target calendars are the same"}

    with closing(sqlite3.connect(DB_PATH)) as conn:
        target = conn.execute(
            "SELECT 1 FROM calendars WHERE id = ?", (target_calendar_id,)
        ).fetchone()
        if target is None:
            return {"error": f"target calendar {target_calendar_id} not found"}

        events = _select_events(conn, source_calendar_id, start_date, end_date)
        if not events:
            return {"moved": 0, "events": []}

        ids = [e["id"] for e in events]
        placeholders = ",".join("?" for _ in ids)
        with conn:
            conn.execute(
                f"UPDATE events SET calendar_id = ? WHERE id IN ({placeholders})",
                [target_calendar_id, *ids],
            )

    return {"moved": len(events), "events": events}
